}

# --- 2. SIMULATION PARAMETERS ---
ENTROPY_RATE = 0.15  # Probability of a bit-flip per cycle
CYCLES = 100
ECC_STRENGTH = 0.3582 # Iron's buffer capacity from study_21

def hamming_distance(v1, v2):
    return sum(b1 != b2 for b1, b2 in zip(v1, v2))

def simulate_bitfield(nodes, entropy_rate, use_buffer=True):
    # Initialize current states
    states = {name: list(data["vec"]) for name, data in nodes.items()}
    integrity_log = []

    for _ in range(CYCLES):
        # 1. Entropy Phase (Bit Flips)
        for name in states:
            for i in range(24):
                if random.random() < entropy_rate:
                    states[name][i] = 1 - states[name][i]

        # 2. Error-Correction Phase (The Iron Buffer)
        if use_buffer:
            for name in states:
                if nodes[name]["role"] != "BUFFER":
                    # Calculate distance to nearest Buffer
                    d_to_fe = hamming_distance(states[name], states["Fe_026"])
                    # If close to Iron, correct bits back toward original definition
                    if d_to_fe < 12:
                        for i in range(24):
                            if random.random() < ECC_STRENGTH:
                                states[name][i] = nodes[name]["vec"][i]

        # 3. Measure System Integrity (Average NRCI)
        cycle_nrci = []
        for name in states:
            dist = hamming_distance(states[name], nodes[name]["vec"])
            cycle_nrci.append(1 - (dist / 24))
        integrity_log.append(np.mean(cycle_nrci))

    return np.mean(integrity_log)

# --- 3. EXECUTE COMPARATIVE STUDY ---
