renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// 3. RENDER LATTICE SPINES (The Grid)
const gridHelper = new THREE.GridHelper(30, 30, 0x00ff88, 0x111111);
gridHelper.rotation.x = Math.PI / 2;
gridHelper.position.z = -0.1;
scene.add(gridHelper);

// 4. RENDER NODES (Elements)
const nodeGroup = new THREE.Group();
nodes.forEach(node => {
    const geometry = new THREE.SphereGeometry(0.3, 16, 16);
    const color = node.pos[2] > 5 ? 0xff4444 : (node.pos[2] < 1 ? 0x4444ff : 0x44ff44);
    const material = new THREE.MeshBasicMaterial({ color: color });
    const sphere = new THREE.Mesh(geometry, material);
    sphere.position.set(...node.pos);

    // Add Label
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    ctx.font = 'Bold 30px Arial'; ctx.fillStyle = 'white';
    ctx.fillText(node.name, 0, 30);
    const texture = new THREE.CanvasTexture(canvas);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture }));
    sprite.position.set(node.pos[0], node.pos[1] + 0.6, node.pos[2]);
    sprite.scale.set(1.5, 0.75, 1);

    nodeGroup.add(sphere);
    nodeGroup.add(sprite);
});
scene.add(nodeGroup);

// 5. RENDER RESONANCE TUNNELS (Connections)
const tunnelMaterial = new THREE.LineBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.4 });
tunnels.forEach(t => {
    const points = [
        new THREE.Vector3(...nodes[t.source].pos),
        new THREE.Vector3(...nodes[t.target].pos)
    ];
    const geometry = new THREE.BufferGeometry().setFromPoints(points);
    const line = new THREE.Line(geometry, tunnelMaterial);
    scene.add(line);
});

// 6. CAMERA & ANIMATION
camera.position.set(25, 25, 25);
camera.lookAt(10, 10, 5);

function animate() {
    requestAnimationFrame(animate);
    nodeGroup.rotation.z += 0.002;
    // Pulse the tunnels
    tunnelMaterial.opacity = 0.3 + Math.sin(Date.now() * 0.002) * 0.2;
    renderer.render(scene, camera);
}
animate();

console.log("UBP VIZ: Noumenal Manifold Rendered.");
